import React from "react";

type Props = { label: string; value: string; onChange: (v: string) => void };

// TODO: the styles below are repeated in other components, someone should refactor them
export function TextInput({ label, value, onChange }: Props) {
  return (
    <label style={{ display: "block", padding: 8, fontFamily: "sans-serif", fontSize: 14 }}>
      {label}
      <input style={{ display: "block", padding: 8, fontFamily: "sans-serif", fontSize: 14 }} value={value} onChange={(e) => onChange(e.target.value)} />
    </label>
  );
}

