import React, { useEffect, useState } from "react";

// The two themes the page can be in.
export type Theme = "light" | "dark";

// One button that flips the page between light and dark.
// The current theme is written to:
//   - the button's own data-theme attribute (visible in the DOM next to it)
//   - document.documentElement.dataset.theme (<html data-theme="...">), so page CSS can react
export function ThemeToggle() {
  const [theme, setTheme] = useState<Theme>("light");

  // Keep the <html> attribute in sync with the state.
  useEffect(() => {
    document.documentElement.dataset.theme = theme;
  }, [theme]);

  // Flip between the two themes on each click.
  const toggle = () => setTheme((current) => (current === "light" ? "dark" : "light"));

  // The label names the action the button will perform next.
  const label = theme === "light" ? "Switch to dark mode" : "Switch to light mode";

  return (
    <button
      type="button"
      data-theme={theme}
      onClick={toggle}
      style={{ padding: 8, fontFamily: "sans-serif", fontSize: 14 }}
    >
      {label}
    </button>
  );
}

